css:
.loader { --accent: var(--loader-color); --accent-2: var(--loader-secondary-color); width: var(--loader-size); height: var(--loader-size); position: relative; animation: beat calc(var(--loader-speed) * 1.2) ease-in-out infinite; }
.loader span { position: absolute; top: 32%; left: 50%; width: 42%; height: 42%; transform: translateX(-50%) rotate(-45deg); background: linear-gradient(45deg, var(--accent-2), var(--accent)); box-shadow: 0 0 calc(var(--loader-size) * .18) color-mix(in srgb, var(--accent) 55%, transparent); }
.loader span::before, .loader span::after { content: ''; position: absolute; width: 100%; height: 100%; border-radius: 50%; background: inherit; }
.loader span::before { top: -50%; left: 0; }
.loader span::after { top: 0; left: 50%; }
@keyframes beat { 0%, 100% { transform: scale(.82); } 15% { transform: scale(1.05); } 30% { transform: scale(.9); } 45% { transform: scale(1); } 60% { transform: scale(.82); } }
